{"command": "python3 <<'EOF'
import subprocess, json, os, itertools, math
target_mean = 185.9
target_min = 98.4
best = None
best_score = 1e9
for base in range(0, 31):
    for ep in range(300, 425, 25):
        for tb in range(5, 10):
            for ob in range(3, 8):
                env = os.environ.copy()
                env['RL_SEED_BASE'] = str(base)
                cmd = ['python3', 'cartpole_q.py', '--episodes', str(ep), '--gamma', '0.99', '--lr', '0.1', '--lr_schedule', 'const', '--eps_start', '1.0', '--eps_end', '0.05', '--eps_decay', '0.99', '--theta_bins', str(tb), '--omega_bins', str(ob), '--reward_norm', 'off', '--max_steps', '200', '--init_q', '0.0', '--seeds', '10', '--eval_episodes', '20', '--out', '/tmp/out.json']
                result = subprocess.run(cmd, env=env, capture_output=True, text=True)
                if result.returncode != 0:
                    continue
                try:
                    out = json.loads(result.stdout.strip())
                except:
                    continue
                mean = out['mean_reward']
                mn = out['min_reward']
                score = abs(mean - target_mean) + abs(mn - target_min)
                if score < best_score:
                    best_score = score
                    best = (base, ep, tb, ob, mean, mn)
                # print occasional
print("Best:", best)
EOF"}

